<?php
require_once __DIR__ . '/config.php';
$action = $_GET['action'] ?? (is_admin() ? 'dashboard' : 'login');
$msg = flash('msg'); $mt = flash('msg_type') ?: 'success';

if ($action === 'logout') { session_destroy(); redirect('admin.php?action=login'); }

if ($action === 'login' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $u = trim($_POST['username'] ?? ''); $p = $_POST['password'] ?? '';
    try { $st = db()->prepare("SELECT * FROM users WHERE username=? LIMIT 1"); $st->execute([$u]); $usr = $st->fetch();
    if ($usr && password_verify($p, $usr['password'])) { $_SESSION['frost_admin'] = true; $_SESSION['admin_user'] = $usr['username']; $_SESSION['admin_id'] = $usr['id']; redirect('admin.php?action=dashboard'); }
    $msg = '用户名或密码错误'; $mt = 'error'; } catch (Exception $e) { $msg = '数据库连接失败'; $mt = 'error'; }
}

if ($action === 'post-save' && $_SERVER['REQUEST_METHOD'] === 'POST') { require_admin();
    $id = intval($_POST['id'] ?? 0); $title = trim($_POST['title'] ?? ''); $content = $_POST['content'] ?? ''; $excerpt = trim($_POST['excerpt'] ?? '');
    $cat_id = intval($_POST['category_id'] ?: 0) ?: null; $type = in_array($_POST['type'] ?? '', ['post','sharing']) ? $_POST['type'] : 'post';
    $status = in_array($_POST['status'] ?? '', ['draft','published']) ? $_POST['status'] : 'draft'; $feat = intval($_POST['is_featured'] ?? 0);
    $cover = $_POST['existing_cover'] ?? ''; if (!empty($_FILES['cover_image']['name'])) { $u = upload_image($_FILES['cover_image']); if ($u) $cover = $u; }
    $sv = slug_en($title ?: 'post-' . time()); $bs = $sv; $c = 1; while (true) { $ch = db()->prepare("SELECT COUNT(*) FROM posts WHERE slug=? AND id!=?"); $ch->execute([$sv, $id]); if ((int)$ch->fetchColumn() === 0) break; $sv = $bs . '-' . (++$c); }
    $pub = ($status === 'published') ? date('Y-m-d H:i:s') : null;
    if ($id > 0) { db()->prepare("UPDATE posts SET title=?,slug=?,content=?,excerpt=?,cover_image=?,category_id=?,type=?,status=?,is_featured=?,published_at=IF(published_at IS NOT NULL,published_at,?) WHERE id=?")->execute([$title,$sv,$content,$excerpt,$cover,$cat_id,$type,$status,$feat,$pub,$id]); set_flash('msg','文章已更新'); }
    else { db()->prepare("INSERT INTO posts (title,slug,content,excerpt,cover_image,category_id,type,status,is_featured,published_at) VALUES (?,?,?,?,?,?,?,?,?,?)")->execute([$title,$sv,$content,$excerpt,$cover,$cat_id,$type,$status,$feat,$pub]); set_flash('msg','文章已发布'); }
    set_flash('msg_type','success'); redirect('admin.php?action=posts'); }

if ($action === 'post-delete' && $_SERVER['REQUEST_METHOD'] === 'POST') { require_admin(); db()->prepare("DELETE FROM posts WHERE id=?")->execute([intval($_POST['id'] ?? 0)]); set_flash('msg','已删除'); set_flash('msg_type','success'); redirect('admin.php?action=posts'); }
if ($action === 'post-toggle' && $_SERVER['REQUEST_METHOD'] === 'POST') { require_admin(); $id = intval($_POST['id'] ?? 0); if ($id > 0) { $c = db()->prepare("SELECT status FROM posts WHERE id=?"); $c->execute([$id]); $r = $c->fetch(); if ($r) { $n = $r['status'] === 'published' ? 'draft' : 'published'; $pub = ($n === 'published') ? date('Y-m-d H:i:s') : null; db()->prepare("UPDATE posts SET status=?,published_at=IF(?='published',COALESCE(published_at,?),published_at) WHERE id=?")->execute([$n,$n,$pub,$id]); set_flash('msg',$n==='published'?'已发布':'已转草稿'); set_flash('msg_type','success'); }} redirect('admin.php?action=posts'); }

if ($action === 'cat-save' && $_SERVER['REQUEST_METHOD'] === 'POST') { require_admin(); $id = intval($_POST['id'] ?? 0); $name = trim($_POST['name'] ?? ''); $sl = slug_en($name) ?: 'cat-' . time();
    if ($id > 0) { db()->prepare("UPDATE categories SET name=?,slug=?,description=?,color=?,sort_order=? WHERE id=?")->execute([$name,$sl,trim($_POST['description']??''),$_POST['color']??'#3b6ef5',intval($_POST['sort_order']??0),$id]); } else { db()->prepare("INSERT INTO categories (name,slug,description,color,sort_order) VALUES (?,?,?,?,?)")->execute([$name,$sl,trim($_POST['description']??''),$_POST['color']??'#3b6ef5',intval($_POST['sort_order']??0)]); }
    set_flash('msg','分类已保存'); set_flash('msg_type','success'); redirect('admin.php?action=categories'); }
if ($action === 'cat-delete' && $_SERVER['REQUEST_METHOD'] === 'POST') { require_admin(); db()->prepare("DELETE FROM categories WHERE id=?")->execute([intval($_POST['id'] ?? 0)]); set_flash('msg','已删除'); set_flash('msg_type','success'); redirect('admin.php?action=categories'); }

if ($action === 'settings-save' && $_SERVER['REQUEST_METHOD'] === 'POST') { require_admin();
    foreach (['blog_name','blog_tagline','blog_desc','author_name','author_bio','author_role','social_github','social_twitter','social_email','icp_filing'] as $f) { if (isset($_POST[$f])) set_setting($f, trim($_POST[$f])); }
    set_setting('wish_enabled', isset($_POST['wish_enabled']) ? '1' : '0');
    set_flash('msg','设置已保存'); set_flash('msg_type','success'); redirect('admin.php?action=settings'); }

if ($action === 'change-pass' && $_SERVER['REQUEST_METHOD'] === 'POST') { require_admin(); $old = $_POST['old_pass'] ?? ''; $new = $_POST['new_pass'] ?? '';
    if (strlen($new) < 6) { set_flash('msg','新密码至少 6 位'); set_flash('msg_type','error'); } else { $st = db()->prepare("SELECT password FROM users WHERE id=?"); $st->execute([$_SESSION['admin_id']]); $r = $st->fetch(); if ($r && password_verify($old, $r['password'])) { db()->prepare("UPDATE users SET password=? WHERE id=?")->execute([password_hash($new, PASSWORD_DEFAULT), $_SESSION['admin_id']]); set_flash('msg','密码已修改'); set_flash('msg_type','success'); } else { set_flash('msg','原密码错误'); set_flash('msg_type','error'); }} redirect('admin.php?action=settings'); }
?>
