case 'wishes':
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['act'])){require_admin();$wid=intval($_POST['id']??0);if($wid){
    if($_POST['act']==='hide'){db()->prepare("UPDATE wishes SET status='hidden' WHERE id=?")->execute([$wid]);set_flash('msg','已隐藏');}
    elseif($_POST['act']==='show'){db()->prepare("UPDATE wishes SET status='visible' WHERE id=?")->execute([$wid]);set_flash('msg','已恢复');}
    elseif($_POST['act']==='del'){db()->prepare("DELETE FROM wishes WHERE id=?")->execute([$wid]);set_flash('msg','已删除');}
    set_flash('msg_type','success');redirect('admin.php?action=wishes');}}
